PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lists(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS memberships(list_id TEXT NOT NULL REFERENCES lists(id),user_id TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(list_id,user_id));
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,reference TEXT UNIQUE NOT NULL,list_id TEXT NOT NULL REFERENCES lists(id),parent_id TEXT REFERENCES tasks(id),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',complete INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 1,position INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS tasks_parent ON tasks(parent_id);
CREATE INDEX IF NOT EXISTS tasks_list ON tasks(list_id,position);
CREATE TABLE IF NOT EXISTS idempotency(actor TEXT NOT NULL,key TEXT NOT NULL,payload TEXT NOT NULL,response TEXT NOT NULL,PRIMARY KEY(actor,key));
CREATE TABLE IF NOT EXISTS history(seq INTEGER PRIMARY KEY AUTOINCREMENT,list_id TEXT NOT NULL REFERENCES lists(id),event TEXT NOT NULL);
